macro_rules! HeuristicFrequencyRank {
    () => {
        # [doc = " This trait allows the user to customize the heuristic used to determine the"] # [doc = " relative frequency of a given byte in the dataset being searched."] # [doc = ""] # [doc = " The use of this trait can have a dramatic impact on performance depending"] # [doc = " on the type of data being searched. The details of why are explained in the"] # [doc = " docs of [`crate::memmem::Prefilter`]. To summarize, the core algorithm uses"] # [doc = " a prefilter to quickly identify candidate matches that are later verified"] # [doc = " more slowly. This prefilter is implemented in terms of trying to find"] # [doc = " `rare` bytes at specific offsets that will occur less frequently in the"] # [doc = " dataset. While the concept of a `rare` byte is similar for most datasets,"] # [doc = " there are some specific datasets (like binary executables) that have"] # [doc = " dramatically different byte distributions. For these datasets customizing"] # [doc = " the byte frequency heuristic can have a massive impact on performance, and"] # [doc = " might even need to be done at runtime."] # [doc = ""] # [doc = " The default implementation of `HeuristicFrequencyRank` reads from the"] # [doc = " static frequency table defined in `src/memmem/byte_frequencies.rs`. This"] # [doc = " is optimal for most inputs, so if you are unsure of the impact of using a"] # [doc = " custom `HeuristicFrequencyRank` you should probably just use the default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memchr::{"] # [doc = "     arch::all::packedpair::HeuristicFrequencyRank,"] # [doc = "     memmem::FinderBuilder,"] # [doc = " };"] # [doc = ""] # [doc = " /// A byte-frequency table that is good for scanning binary executables."] # [doc = " struct Binary;"] # [doc = ""] # [doc = " impl HeuristicFrequencyRank for Binary {"] # [doc = "     fn rank(&self, byte: u8) -> u8 {"] # [doc = "         const TABLE: [u8; 256] = ["] # [doc = "             255, 128, 61, 43, 50, 41, 27, 28, 57, 15, 21, 13, 24, 17, 17,"] # [doc = "             89, 58, 16, 11, 7, 14, 23, 7, 6, 24, 9, 6, 5, 9, 4, 7, 16,"] # [doc = "             68, 11, 9, 6, 88, 7, 4, 4, 23, 9, 4, 8, 8, 5, 10, 4, 30, 11,"] # [doc = "             9, 24, 11, 5, 5, 5, 19, 11, 6, 17, 9, 9, 6, 8,"] # [doc = "             48, 58, 11, 14, 53, 40, 9, 9, 254, 35, 3, 6, 52, 23, 6, 6, 27,"] # [doc = "             4, 7, 11, 14, 13, 10, 11, 11, 5, 2, 10, 16, 12, 6, 19,"] # [doc = "             19, 20, 5, 14, 16, 31, 19, 7, 14, 20, 4, 4, 19, 8, 18, 20, 24,"] # [doc = "             1, 25, 19, 58, 29, 10, 5, 15, 20, 2, 2, 9, 4, 3, 5,"] # [doc = "             51, 11, 4, 53, 23, 39, 6, 4, 13, 81, 4, 186, 5, 67, 3, 2, 15,"] # [doc = "             0, 0, 1, 3, 2, 0, 0, 5, 0, 0, 0, 2, 0, 0, 0,"] # [doc = "             12, 2, 1, 1, 3, 1, 1, 1, 6, 1, 2, 1, 3, 1, 1, 2, 9, 1, 1, 0,"] # [doc = "             2, 2, 4, 4, 11, 6, 7, 3, 6, 9, 4, 5,"] # [doc = "             46, 18, 8, 18, 17, 3, 8, 20, 16, 10, 3, 7, 175, 4, 6, 7, 13,"] # [doc = "             3, 7, 3, 3, 1, 3, 3, 10, 3, 1, 5, 2, 0, 1, 2,"] # [doc = "             16, 3, 5, 1, 6, 1, 1, 2, 58, 20, 3, 14, 12, 2, 1, 3, 16, 3, 5,"] # [doc = "             8, 3, 1, 8, 6, 17, 6, 5, 3, 8, 6, 13, 175,"] # [doc = "         ];"] # [doc = "         TABLE[byte as usize]"] # [doc = "     }"] # [doc = " }"] # [doc = " // Create a new finder with the custom heuristic."] # [doc = " let finder = FinderBuilder::new()"] # [doc = "     .build_forward_with_ranker(Binary, b\"\\x00\\x00\\xdd\\xdd\");"] # [doc = " // Find needle with custom heuristic."] # [doc = " assert!(finder.find(b\"\\x00\\x00\\x00\\xdd\\xdd\").is_some());"] # [doc = " ```"] pub trait HeuristicFrequencyRank { # [doc = " Return the heuristic frequency rank of the given byte. A lower rank"] # [doc = " means the byte is believed to occur less frequently in the haystack."] # [doc = ""] # [doc = " Some uses of this heuristic may treat arbitrary absolute rank values as"] # [doc = " significant. For example, an implementation detail in this crate may"] # [doc = " determine that heuristic prefilters are inappropriate if every byte in"] # [doc = " the needle has a \"high\" rank."] fn rank (& self , byte : u8) -> u8 ; }
    };
}

HeuristicFrequencyRank!()